<?php
declare(strict_types=1); namespace Theobroma\OneC\Http;
final class ExchangeFileStore {private string$dir;public function __construct(string$base,string$session,private readonly int$limit){$this->dir=rtrim($base,'/\\').DIRECTORY_SEPARATOR.hash('sha256',$session);}public function append(string$name,string$chunk):void{$path=$this->path($name);if(!is_dir($this->dir)&&!mkdir($this->dir,0700,true)&&!is_dir($this->dir))throw new \RuntimeException('Cannot create exchange directory');$current=is_file($path)?(int)filesize($path):0;if($current+strlen($chunk)>$this->limit)throw new \LengthException('XML exceeds configured limit');$h=fopen($path,'c+b');if(!$h)throw new \RuntimeException('Cannot open exchange file');try{if(!flock($h,LOCK_EX))throw new \RuntimeException('Cannot lock exchange file');fseek($h,0,SEEK_END);if(fwrite($h,$chunk)!==strlen($chunk))throw new \RuntimeException('Cannot write exchange file');fflush($h);flock($h,LOCK_UN);}finally{fclose($h);}}public function read(string$name):string{$path=$this->path($name);if(!is_file($path))throw new \RuntimeException('Exchange file not found');$v=file_get_contents($path);if($v===false)throw new \RuntimeException('Cannot read exchange file');return$v;}public function delete(string$name):void{$path=$this->path($name);if(is_file($path))unlink($path);if(is_dir($this->dir)&&count(scandir($this->dir)?:[])===2)rmdir($this->dir);}public function exists(string$name):bool{return is_file($this->path($name));}private function path(string$name):string{if($name!==basename($name)||preg_match('/^[A-Za-z0-9._-]+\.xml$/i',$name)!==1)throw new \InvalidArgumentException('Unsafe XML filename');return$this->dir.DIRECTORY_SEPARATOR.$name;}}
